 pub fn begin_frame(&mut self,snapshot:&LayoutSnapshot,frame:&Frame)->Result<(),&'static str>{if self.has_active(){return Err("layout-export-text-plan-active".into());}let Frame::Text{bounds,story_id,inset,..}=frame else{return Err("layout-export-text-frame-required".into());};let story=snapshot.stories.iter().position(|story|story.id==*story_id).ok_or("layout-export-story-missing")?;self.begin_story_frame(snapshot,frame,story)}
 pub fn begin_story_frame(&mut self,snapshot:&LayoutSnapshot,frame:&Frame,story:usize)->Result<(),&'static str>{let Frame::Text{bounds,inset,..}=frame else{return Err("layout-text-frame-required".into());};let x=inset.x.max(0.0);let y=inset.y.max(0.0);let width=(bounds.width.min(inset.x+inset.width)-x).max(0.0);self.begin_story_box(snapshot,story,[bounds.x+x,bounds.y+y],width,bounds.rotation as f32,[(bounds.x+bounds.width*0.5)as f32,(bounds.y+bounds.height*0.5)as f32])}
 pub fn begin_story_box(&mut self,snapshot:&LayoutSnapshot,story:usize,origin:[f64;2],width:f64,rotation:f32,center:[f32;2])->Result<(),&'static str>{if self.has_active()||story>=snapshot.stories.len(){return Err("layout-paragraph-source-invalid".into());}let paragraph=snapshot.paragraph_styles.first();let size=paragraph.map_or(12.0,|p|p.font_size);let line_height=paragraph.map_or(14.4,|p|p.leading);let tracking=paragraph.map_or(0.0,|p|p.tracking);let alignment=match paragraph.map(|p|p.alignment.as_str()).unwrap_or("left"){"center"|"middle"=>ParagraphAlignment::Center,"right"=>ParagraphAlignment::Right,"justify"|"justified"=>ParagraphAlignment::Justify,_=>ParagraphAlignment::Left};let count=snapshot.stories[story].style_runs.len().checked_add(1).ok_or("layout-paragraph-style-count")?;self.owners.active=Some(TextPlan{base_span:FontRunSpan{start:0,end:snapshot.stories[story].content.len(),size,tracking,face:face_index(paragraph.map_or("Layout Sans",|p|p.font_family.as_str()),self.font_count)},base_color:[0.0,0.0,0.0,1.0],base_italic:false,base_metadata:StyleRef{paragraph:(!snapshot.paragraph_styles.is_empty()).then_some(0),character:None,weight:paragraph.map_or(400,|style|style.font_weight),italic:false},base_ready:false,style_count:count,document:Some(snapshot as*const LayoutSnapshot as usize),flow:None,height:None,region_finished:false,empty:width<=0.0,source:TextSource::Story(story),spans:Vec::new(),colors:Vec::new(),italics:Vec::new(),metadata:Vec::new(),cursor:None,output:None,style:ParagraphStyle{width:width.max(1.0),origin,size,line_height,tracking,alignment},rotation,center,style_at:0,glyph_at:0,lookup_at:0,paragraph:None,character:None,lookup_phase:0});Ok(())}
 fn initialize(plan:&mut TextPlan,work:&mut FontWorkLedger)->Result<bool,&'static str>{if plan.base_ready{return Ok(true);}if !work.contiguous(&mut plan.spans,plan.style_count)?||!work.contiguous(&mut plan.colors,plan.style_count)?||!work.contiguous(&mut plan.italics,plan.style_count)?||!work.contiguous(&mut plan.metadata,plan.style_count)?{return Ok(false);}if !work.vec_slot(&mut plan.spans)?||!work.vec_slot(&mut plan.colors)?||!work.vec_slot(&mut plan.italics)?||!work.vec_slot(&mut plan.metadata)?{return Ok(false);}work.vec_push(&mut plan.spans,plan.base_span).map_err(|_|"layout-paragraph-base-span-copy")?;work.vec_push(&mut plan.colors,plan.base_color).map_err(|_|"layout-paragraph-base-color-copy")?;work.vec_push(&mut plan.italics,plan.base_italic).map_err(|_|"layout-paragraph-base-italic-copy")?;work.vec_push(&mut plan.metadata,plan.base_metadata).map_err(|_|"layout-paragraph-base-style-copy")?;plan.base_ready=true;Ok(true)}
