 fn advance_source_parts<S:FlowFrameSource+?Sized>(owners:&mut TextOwners,font_count:usize,font_at:&mut usize,snapshot:&LayoutSnapshot,external:Option<(usize,&str)>,frames:Option<&S>,work:&mut FontWorkLedger)->Result<LayoutParagraphTurn,&'static str>{if owners.active.is_none(){return Ok(LayoutParagraphTurn::Complete);}if owners.active.as_ref().unwrap().document.is_some_and(|document|document!=snapshot as*const LayoutSnapshot as usize){return Err("layout-paragraph-document-source-changed");}match &owners.active.as_ref().unwrap().source{TextSource::Link{index,document,pointer,length}=>{let value=snapshot.links.get(*index).ok_or("layout-paragraph-link-missing")?.artifact_kind.as_str();if *document!=snapshot as*const LayoutSnapshot as usize||value.as_ptr()as usize!=*pointer||value.len()!=*length{return Err("layout-paragraph-link-source-changed".into());}},TextSource::External{index,pointer,length}=>{let(actual,value)=external.ok_or("layout-paragraph-external-source-required")?;if actual!=*index||value.as_ptr()as usize!=*pointer||value.len()!=*length{return Err("layout-paragraph-external-source-changed".into());}},_=>{}}if owners.active.as_ref().is_some_and(|plan|plan.empty){if !work.slot(&mut owners.plans)?{return Ok(LayoutParagraphTurn::Pending);}let mut plan=owners.active.take().unwrap();plan.output=Some(FontParagraph{glyphs:PagedList::new(),segments:PagedList::new(),lines:PagedList::new(),width:0.0,height:0.0});{let value=plan;work.push(&mut owners.plans,value)}.map_err(|_|"layout-paragraph-empty-reservation")?;return Ok(LayoutParagraphTurn::Complete);}if !Self::ready_one(owners,font_count,font_at,work)?{return Ok(LayoutParagraphTurn::Pending);}if !Self::initialize(owners.active.as_mut().unwrap(),work)?{return Ok(LayoutParagraphTurn::Pending);}let source=owners.plans.len();let plan=owners.active.as_mut().ok_or("layout-export-text-plan-missing")?;let story=match &plan.source{TextSource::Story(index)=>Some(&snapshot.stories[*index]),TextSource::Link{..}|TextSource::Label(_)|TextSource::External{..}=>None};let content=match &plan.source{TextSource::Story(index)=>snapshot.stories[*index].content.as_str(),TextSource::Link{index,document,pointer,length}=>{if *document!=snapshot as*const LayoutSnapshot as usize{return Err("layout-paragraph-link-source-changed".into());}let value=snapshot.links.get(*index).ok_or("layout-paragraph-link-missing")?.artifact_kind.as_str();if value.as_ptr()as usize!=*pointer||value.len()!=*length{return Err("layout-paragraph-link-source-changed".into());}value},TextSource::Label(value)=>value.as_str(),TextSource::External{index,pointer,length}=>{let (actual,value)=external.ok_or("layout-paragraph-external-source-required")?;if actual!=*index||value.as_ptr()as usize!=*pointer||value.len()!=*length{return Err("layout-paragraph-external-source-changed".into());}value}};if let Some(story)=story.filter(|story|plan.style_at<story.style_runs.len()){let run=&story.style_runs[plan.style_at];if plan.lookup_phase==0{if let Some(id)=run.paragraph_style_id.as_ref(){if let Some(style)=snapshot.paragraph_styles.get(plan.lookup_at){let at=plan.lookup_at;plan.lookup_at+=1;if style.id==*id{plan.paragraph=Some(at);plan.lookup_phase=1;plan.lookup_at=0;}return Ok(LayoutParagraphTurn::Pending);}}plan.lookup_phase=1;plan.lookup_at=0;return Ok(LayoutParagraphTurn::Pending);}if plan.lookup_phase==1{if let Some(id)=run.character_style_id.as_ref(){if let Some(style)=snapshot.character_styles.get(plan.lookup_at){let at=plan.lookup_at;plan.lookup_at+=1;if style.id==*id{plan.character=Some(at);plan.lookup_phase=2;}return Ok(LayoutParagraphTurn::Pending);}}plan.lookup_phase=2;return Ok(LayoutParagraphTurn::Pending);}if !work.vec_slot(&mut plan.spans)?||!work.vec_slot(&mut plan.colors)?||!work.vec_slot(&mut plan.italics)?||!work.vec_slot(&mut plan.metadata)?{return Ok(LayoutParagraphTurn::Pending);}let paragraph=plan.paragraph.and_then(|index|snapshot.paragraph_styles.get(index));let character=plan.character.and_then(|index|snapshot.character_styles.get(index));let size=character.and_then(|s|s.font_size).or_else(||paragraph.map(|s|s.font_size)).unwrap_or(plan.style.size);let tracking=character.and_then(|s|s.tracking).or_else(||paragraph.map(|s|s.tracking)).unwrap_or(plan.style.tracking);let family=character.and_then(|s|s.font_family.as_deref()).or_else(||paragraph.map(|s|s.font_family.as_str())).or_else(||snapshot.paragraph_styles.first().map(|s|s.font_family.as_str())).unwrap_or("Layout Sans");work.vec_push(&mut plan.spans,FontRunSpan{start:run.start as usize,end:run.end as usize,size,tracking,face:face_index(family,font_count)}).map_err(|_|"layout-paragraph-style-span-copy")?;work.vec_push(&mut plan.colors,character.and_then(|s|s.color).unwrap_or([0.0,0.0,0.0,1.0])).map_err(|_|"layout-paragraph-style-color-copy")?;work.vec_push(&mut plan.italics,character.and_then(|s|s.italic).unwrap_or(false)).map_err(|_|"layout-paragraph-style-italic-copy")?;work.vec_push(&mut plan.metadata,StyleRef{paragraph:plan.paragraph.or((!snapshot.paragraph_styles.is_empty()).then_some(0)),character:plan.character,weight:character.and_then(|style|style.font_weight).or_else(||paragraph.map(|style|style.font_weight)).unwrap_or_else(||snapshot.paragraph_styles.first().map_or(400,|style|style.font_weight)),italic:character.and_then(|style|style.italic).unwrap_or(false)}).map_err(|_|"layout-paragraph-style-metadata-copy")?;plan.lookup_at=0;plan.paragraph=None;plan.character=None;plan.lookup_phase=0;plan.style_at+=1;return Ok(LayoutParagraphTurn::Pending);}if let Some(flow)=plan.flow.as_mut(){let frames=frames.ok_or("layout-paragraph-flow-source-required")?;if !flow.active{match flow.cursor.advance_source(frames,content,1).map_err(|code|code)?{FlowStep::Progress=>return Ok(LayoutParagraphTurn::Pending),FlowStep::Cancelled=>return Err("layout-paragraph-flow-cancelled".into()),FlowStep::Region(region)=>{if !work.slot(&mut flow.regions)?{return Ok(LayoutParagraphTurn::Pending);}if plan.cursor.is_none(){plan.cursor=Some(FontParagraphCursor::new(content,owners.fonts.len(),plan.style,&plan.spans,FontOutlineLimits::default(),owners.unicode.as_ref().unwrap().layout,owners.line.as_ref().unwrap().layout));}plan.cursor.as_mut().unwrap().supply_region(ParagraphRegion{width:region.rect.width,height:region.rect.height,origin:[region.rect.x,region.rect.y]})?;{let value=region;work.push(&mut flow.regions,value)}.map_err(|_|"layout-paragraph-flow-region-reservation")?;flow.active=true;return Ok(LayoutParagraphTurn::Pending);},terminal @ (FlowStep::Done|FlowStep::Overset)=>{flow.overset=matches!(terminal,FlowStep::Overset);if plan.cursor.is_none(){plan.empty=true;return Ok(LayoutParagraphTurn::Pending);}plan.cursor.as_mut().unwrap().finish_flow()?;flow.active=true;return Ok(LayoutParagraphTurn::Pending);}}}}if plan.cursor.is_none(){let mut cursor=FontParagraphCursor::new(content,owners.fonts.len(),plan.style,&plan.spans,FontOutlineLimits::default(),owners.unicode.as_ref().unwrap().layout,owners.line.as_ref().unwrap().layout);if let Some(height)=plan.height{cursor.supply_region(ParagraphRegion{width:plan.style.width,height,origin:plan.style.origin})?;}plan.cursor=Some(cursor);return Ok(LayoutParagraphTurn::Pending);}if plan.output.is_none(){if plan.cursor.as_mut().unwrap().advance(content,&owners.fonts,&plan.spans,owners.unicode.as_ref().unwrap().source.as_ref(),owners.line.as_ref().unwrap().source.as_ref(),1,work)?.done{plan.output=Some(plan.cursor.as_mut().unwrap().take_result()?);if let Some(flow)=plan.flow.as_mut(){if !flow.cursor.terminal_is_empty(){flow.cursor.accept(content,content.len()).map_err(|code|code)?;}}}else if let Some(pause)=plan.cursor.as_ref().unwrap().flow_pause(){if let Some(flow)=plan.flow.as_mut(){flow.cursor.accept(content,pause.source_end).map_err(|code|code)?;flow.active=false;}else if plan.height.is_some()&&!plan.region_finished{plan.cursor.as_mut().unwrap().finish_flow()?;plan.region_finished=true;}else{return Err("layout-paragraph-unexpected-flow-pause".into());}}return Ok(LayoutParagraphTurn::Pending);}let paragraph=plan.output.as_ref().unwrap();if paragraph.glyphs.get(plan.glyph_at).is_some(){if plan.flow.as_ref().is_some_and(|flow|flow.target.is_some())&&!work.copy_bytes(std::mem::size_of::<FrameGlyphRange>()){return Ok(LayoutParagraphTurn::Pending);}let glyph=plan.glyph_at;plan.glyph_at+=1;if let Some(target)=plan.flow.as_ref().and_then(|flow|flow.target){let region=Self::plan_region(plan,glyph)?.ok_or("layout-paragraph-flow-region")?;let range=owners.frames.get_mut(region.frame).ok_or("layout-paragraph-frame-range")?;if range.source.is_none()||range.start==range.end{range.start=glyph;}range.source=Some(source);range.end=glyph+1;if region.frame!=target{return Ok(LayoutParagraphTurn::Pending);}}return Ok(LayoutParagraphTurn::Glyph(Self::glyph_turn(plan,source,glyph)?));}if !work.slot(&mut owners.plans)?{return Ok(LayoutParagraphTurn::Pending);}{let value=owners.active.take().unwrap();work.push(&mut owners.plans,value)}.map_err(|_|"layout-export-paragraph-reservation")?;Ok(LayoutParagraphTurn::Complete)}
 pub fn line(&self,source:usize,index:usize)->Result<Option<&semio_framework_2d_text_font_run::paragraph::ParagraphLine>,&'static str>{Ok(self.plan(source)?.output.as_ref().ok_or("layout-paragraph-not-ready")?.lines.get(index))}
 pub fn line_count(&self,source:usize)->Result<usize,&'static str>{Ok(self.plan(source)?.output.as_ref().ok_or("layout-paragraph-not-ready")?.lines.len())}
 fn plan(&self,source:usize)->Result<&TextPlan,&'static str>{if source==self.owners.plans.len(){self.owners.active.as_ref()}else{self.owners.plans.get(source)}.ok_or_else(||"layout-paragraph-missing".into())}
 pub fn glyph_cluster<'a>(&'a self,snapshot:&'a LayoutSnapshot,source:usize,glyph:usize)->Result<LayoutTextCluster<'a>,&'static str>{let plan=self.plan(source)?;let output=plan.output.as_ref().ok_or("layout-export-paragraph-missing")?;let record=output.glyphs.get(glyph).ok_or("layout-export-paragraph-glyph-missing")?;let content=match &plan.source{TextSource::Story(index)=>snapshot.stories.get(*index).ok_or("layout-export-story-missing")?.content.as_str(),TextSource::Link{index,document,pointer,length}=>{if *document!=snapshot as*const LayoutSnapshot as usize{return Err("layout-paragraph-link-source-changed".into());}let value=snapshot.links.get(*index).ok_or("layout-paragraph-link-missing")?.artifact_kind.as_str();if value.as_ptr()as usize!=*pointer||value.len()!=*length{return Err("layout-paragraph-link-source-changed".into());}value},TextSource::Label(value)=>value.as_str(),TextSource::External{..}=>return Err("layout-paragraph-external-cluster-required".into())};let end=plan.cursor.as_ref().ok_or("layout-export-paragraph-cursor-missing")?.cluster_end(record.source_at)?;let line=output.lines.get(record.line).ok_or("layout-export-paragraph-line-missing")?;let range=record.source_at..end.min(line.end);let text=content.get(range.clone()).ok_or("layout-export-paragraph-cluster-invalid")?;let first_glyph=glyph==0||output.glyphs.get(glyph-1).unwrap().source_at!=record.source_at;Ok(LayoutTextCluster{text,range,first_glyph})}
