 pub fn segment(&self,source:usize,glyph:usize,at:usize)->Result<Option<&semio_framework_2d_engine::PathSegment>,&'static str>{let paragraph=self.plan(source).ok().and_then(|plan|plan.output.as_ref()).ok_or("layout-export-paragraph-missing")?;let glyph=paragraph.glyphs.get(glyph).ok_or("layout-export-paragraph-glyph-missing")?;Ok((at<glyph.segment_count).then(||paragraph.segments.get(glyph.segment_start+at)).flatten())}
