 pub fn flow_overset(&self,source:usize)->Result<bool,&'static str>{Ok(self.plan(source)?.flow.as_ref().is_some_and(|flow|flow.overset))}
 pub fn glyph_style<'a>(&'a self,snapshot:&'a LayoutSnapshot,source:usize,glyph:usize)->Result<LayoutGlyphStyle<'a>,&'static str>{let plan=self.plan(source)?;let record=self.glyph(source,glyph)?;let style=plan.metadata.get(record.style.unwrap_or(0)).ok_or("layout-paragraph-style-missing")?;let paragraph=style.paragraph.and_then(|index|snapshot.paragraph_styles.get(index));let character=style.character.and_then(|index|snapshot.character_styles.get(index));let family=character.and_then(|style|style.font_family.as_deref()).or_else(||paragraph.map(|style|style.font_family.as_str())).unwrap_or("Layout Sans");Ok(LayoutGlyphStyle{family,weight:style.weight,italic:style.italic})} pub fn external_cluster<'a>(&'a self,index:usize,content:&'a str,source:usize,glyph:usize)->Result<LayoutTextCluster<'a>,&'static str>{let plan=self.plan(source)?;let TextSource::External{index:expected,pointer,length}=&plan.source else{return Err("layout-paragraph-external-source-required".into());};if index!=*expected||content.as_ptr()as usize!=*pointer||content.len()!=*length{return Err("layout-paragraph-external-source-changed".into());}let output=plan.output.as_ref().ok_or("layout-paragraph-not-ready")?;let record=output.glyphs.get(glyph).ok_or("layout-paragraph-glyph-missing")?;let end=plan.cursor.as_ref().ok_or("layout-paragraph-cursor-missing")?.cluster_end(record.source_at)?;let line=output.lines.get(record.line).ok_or("layout-paragraph-line-missing")?;let range=record.source_at..end.min(line.end);let text=content.get(range.clone()).ok_or("layout-paragraph-cluster-invalid")?;let first_glyph=glyph==0||output.glyphs.get(glyph-1).unwrap().source_at!=record.source_at;Ok(LayoutTextCluster{text,range,first_glyph})}

